contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 first) public payable {
        c.XBornID(); if (__ESBMC_reverted()) return;
        uint256 before = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        c.getTokens(); if (__ESBMC_reverted()) return;
        uint256 after1 = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 credited = after1 - before;
        require(credited > 0);
        require(first <= credited);
        c.getTokens(); if (__ESBMC_reverted()) return;
        assert(c.balanceOf(address(this)) == after1);
    }
    receive() external payable {}
}

