pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 first) internal {
        try c.XBornID() {} catch { return; }
        uint256 before;
        try c.balanceOf(address(this)) returns (uint256 __r) { before = __r; } catch { return; }
        try c.getTokens() {} catch { return; }
        uint256 after1;
        try c.balanceOf(address(this)) returns (uint256 __r) { after1 = __r; } catch { return; }
        uint256 credited = after1 - before;
        vm.assume(credited > 0);
        vm.assume(first <= credited);
        try c.getTokens() {} catch { return; }
        assertTrue(c.balanceOf(address(this)) == after1);
    }

    function testFuzz_run(uint256 first) public {
        _run(first);
    }

    receive() external payable {}
}
